export function reinitializeRunItemStateForFreshStart(world, opts = {}) {
  setIdentificationEnabled(opts.identifyItems !== false);
  resetIdentification();
  identify(TOUCHSTONE_IDENTITY);
  initGemPricing(gemPricingRng(world));
}

